fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if string is empty
    if txt.is_empty() {
        return false;
    }
    
    // Get the last character
    let last_char = match txt.chars().last() {
        Some(c) => c,
        None => return false, // should not happen since we checked is_empty, but safe
    };
    
    // Check if last character is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }
    
    // Check string length
    let char_count = txt.chars().count();
    if char_count == 1 {
        return true;
    }
    
    // Get the second-to-last character
    // We know char_count >= 2 here
    let second_last = txt.chars().rev().nth(1); // nth(1) from rev gives second from end
    match second_last {
        Some(' ') => true,
        _ => false,
    }
}